/**
 * Phone-side publishing planner. A draft is stored only on this device until a
 * configured first-party service acknowledges an upload and returns a stable job ID.
 * Provider OAuth secrets, durable scheduling and actual delivery belong to that
 * service; never display a local draft as a published or confirmed scheduled post.
 */
public final class PublishActivity extends Activity {
    private static final int BG=0xff090b0e,PANEL=0xff191e25,TEXT=0xffedf0f3,MUTED=0xff98a3b2,ACCENT=0xffc2a4ff;
    private static final String[] PLATFORMS={"facebook","linkedin","tiktok","youtube"};
    private static final String[] LABELS={"Facebook Pages","LinkedIn","TikTok","YouTube"};
    private final ExecutorService io=Executors.newSingleThreadExecutor();
    private LinearLayout root,content;private String section="Queue";private Uri pickedMedia;private String pickedName="";private long pickedSize;private PublishDraftStore.Draft editingDraft;private Dialog composer;private TextView mediaLine,scheduleLine;private EditText captionField;private final LinkedHashMap<String,CheckBox> channelBoxes=new LinkedHashMap<>();private long scheduledAt;
    private SharedPreferences prefs;private PublishApiClient api;private ArrayList<PublishDraftStore.Draft> drafts=new ArrayList<>();private JSONObject accounts=new JSONObject(),jobs=new JSONObject();private AlertDialog busy;

    @Override protected void onCreate(Bundle state){super.onCreate(state);getWindow().setStatusBarColor(BG);getWindow().setNavigationBarColor(BG);prefs=getSharedPreferences("publishing",MODE_PRIVATE);api=new PublishApiClient(this,configuredServiceUrl(),PublishCredentialStore.load(this));drafts=PublishDraftStore.load(this);render();handleOAuth(getIntent());refreshServiceData();}
    private String configuredServiceUrl(){if(!BuildConfig.PUBLISHING_SERVICE_URL.trim().isEmpty())return BuildConfig.PUBLISHING_SERVICE_URL.trim();return BuildConfig.DEBUG?prefs.getString("service_url",""):"";}
    private int dp(float n){return Math.round(n*getResources().getDisplayMetrics().density);}
    private LinearLayout column(){LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);return l;}
    private TextView text(String value,int size,int color){TextView t=new TextView(this);t.setText(value);t.setTextSize(size);t.setTextColor(color);t.setPadding(dp(10),dp(5),dp(10),dp(5));return t;}
    private Button button(String title,Runnable action){Button b=new Button(this);b.setText(title);b.setTextSize(12);b.setTextColor(TEXT);b.setBackgroundTintList(android.content.res.ColorStateList.valueOf(PANEL));b.setOnClickListener(v->action.run());return b;}
    private android.graphics.drawable.GradientDrawable card(){android.graphics.drawable.GradientDrawable d=new android.graphics.drawable.GradientDrawable();d.setColor(PANEL);d.setCornerRadius(dp(14));d.setStroke(dp(1),0xff303640);return d;}
    private void render(){root=column();root.setBackgroundColor(BG);root.setPadding(dp(12),dp(6),dp(12),dp(8));setContentView(root);LinearLayout top=new LinearLayout(this);top.setGravity(Gravity.CENTER_VERTICAL);top.addView(button("‹",()->finish()),new LinearLayout.LayoutParams(dp(48),dp(46)));TextView title=text("PUBLISH STUDIO",12,TEXT);title.setTypeface(null,android.graphics.Typeface.BOLD);top.addView(title,new LinearLayout.LayoutParams(0,dp(46),1));Button settings=button("⚙",this::showPublishingSetup);settings.setOnLongClickListener(v->{if(BuildConfig.DEBUG){serviceSettings();return true;}return false;});top.addView(settings,new LinearLayout.LayoutParams(dp(48),dp(46)));root.addView(top);
        LinearLayout tabs=new LinearLayout(this);for(String value:new String[]{"Queue","Calendar","Accounts"}){Button b=button(value,()->{section=value;render();refreshServiceData();});b.setTextColor(section.equals(value)?ACCENT:MUTED);tabs.addView(b,new LinearLayout.LayoutParams(0,dp(44),1));}root.addView(tabs);ScrollView scroll=new ScrollView(this);content=column();content.setPadding(0,dp(6),0,dp(18));scroll.addView(content);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));if(section.equals("Queue"))showQueue();else if(section.equals("Calendar"))showCalendar();else showAccounts();}
    private void serviceBanner(){LinearLayout card=column();card.setPadding(dp(10),dp(8),dp(10),dp(8));card.setBackground(card());card.addView(text("SOCIAL PUBLISHING · COMING SOON",11,ACCENT));card.addView(text("You won’t need to find a server or enter technical settings. We’re preparing account connection and scheduling. Your drafts stay on this phone until then.",12,MUTED));content.addView(card);}
    private void showPublishingSetup(){new AlertDialog.Builder(this).setTitle("Social publishing").setMessage(api.configured()?"Your publishing account setup is not complete yet. Please check back when account connection is available.":"Account connection and scheduled publishing are being prepared. You won’t need a server address, pairing code, or other technical setup. You can still save drafts on this phone.").setPositiveButton("Got it",null).show();}
    private void showQueue(){content.addView(text("Your publishing queue",23,TEXT));content.addView(text("Drafts stay on this phone. A post appears as scheduled only after the service confirms the platform job.",12,MUTED));LinearLayout actions=new LinearLayout(this);actions.addView(button("＋  New post",this::newComposer),new LinearLayout.LayoutParams(0,dp(50),1));actions.addView(button("↻  Refresh",this::refreshServiceData),new LinearLayout.LayoutParams(dp(112),dp(50)));content.addView(actions);if(!api.configured())serviceBanner();else if(PublishCredentialStore.load(this).isEmpty())content.addView(text("Connect a social account in the Accounts tab to get started.",12,MUTED));else if(accounts.optJSONArray("accounts")==null)content.addView(text("Checking your publishing queue…",12,MUTED));content.addView(text("ON THIS PHONE · LOCAL DRAFTS",11,ACCENT));if(drafts.isEmpty())content.addView(emptyCard("No saved drafts","Create a post to prepare a video and channel captions."));else for(PublishDraftStore.Draft d:drafts)content.addView(draftCard(d));content.addView(text("SCHEDULED & PUBLISHED",11,ACCENT));JSONArray queued=jobs.optJSONArray("jobs");if(!api.configured()||PublishCredentialStore.load(this).isEmpty())content.addView(text("Your scheduled and published posts will appear here once account connection is ready.",12,MUTED));else if(queued==null||queued.length()==0)content.addView(emptyCard("Nothing queued yet","Posts scheduled through Solo Camera will appear here."));else for(int i=0;i<queued.length();i++)content.addView(jobCard(queued.optJSONObject(i)));}
    private View emptyCard(String headline,String detail){LinearLayout box=column();box.setPadding(dp(8),dp(8),dp(8),dp(8));box.setBackground(card());box.addView(text(headline,14,TEXT));box.addView(text(detail,11,MUTED));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.bottomMargin=dp(8);box.setLayoutParams(lp);return box;}
    private View draftCard(PublishDraftStore.Draft d){LinearLayout box=column();box.setPadding(dp(8),dp(5),dp(8),dp(8));box.setBackground(card());String when=d.scheduledAt>0?DateFormat.getDateTimeInstance(DateFormat.MEDIUM,DateFormat.SHORT).format(new Date(d.scheduledAt))+" · "+TimeZone.getDefault().getID():"Not scheduled";box.addView(text((d.mediaName.isEmpty()?"Video not selected":d.mediaName)+"  ·  "+d.state.toUpperCase(Locale.ROOT),14,TEXT));box.addView(text(d.platforms.isEmpty()?"No channels selected":channelSummary(d.platforms),11,ACCENT));box.addView(text(when+(d.error.isEmpty()?"":"\n"+d.error),11,MUTED));LinearLayout row=new LinearLayout(this);row.addView(button("Edit",()->editComposer(d)),new LinearLayout.LayoutParams(0,dp(42),1));row.addView(button("Delete",()->deleteDraft(d)),new LinearLayout.LayoutParams(0,dp(42),1));box.addView(row);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.bottomMargin=dp(8);box.setLayoutParams(lp);return box;}
    private View jobCard(JSONObject job){LinearLayout box=column();box.setPadding(dp(8),dp(5),dp(8),dp(8));box.setBackground(card());String provider=job.optString("provider",job.optString("platform","Post"));String status=job.optString("status","queued").replace('_',' ').toUpperCase(Locale.ROOT);box.addView(text(provider+"  ·  "+status,14,TEXT));box.addView(text(job.optString("caption",job.optString("captionPreview","")),12,MUTED));long when=job.optLong("scheduledAt",0);if(when>0)box.addView(text(DateFormat.getDateTimeInstance(DateFormat.MEDIUM,DateFormat.SHORT).format(new Date(when)),11,ACCENT));if(job.has("error"))box.addView(text(job.optString("error"),11,0xffff8f88));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.bottomMargin=dp(8);box.setLayoutParams(lp);return box;}
    private void showCalendar(){content.addView(text("Calendar",23,TEXT));content.addView(text("Upcoming items are grouped by local publishing date. Local drafts are marked separately from confirmed server schedules.",12,MUTED));TreeMap<String,ArrayList<PublishDraftStore.Draft>> byDay=new TreeMap<>();for(PublishDraftStore.Draft d:drafts)if(d.scheduledAt>0){String key=DateFormat.getDateInstance(DateFormat.FULL).format(new Date(d.scheduledAt));byDay.computeIfAbsent(key,k->new ArrayList<>()).add(d);}if(byDay.isEmpty())content.addView(emptyCard("No local scheduled drafts","Choose a date and time while composing a post."));for(Map.Entry<String,ArrayList<PublishDraftStore.Draft>> e:byDay.entrySet()){content.addView(text(e.getKey().toUpperCase(Locale.ROOT),11,ACCENT));for(PublishDraftStore.Draft d:e.getValue())content.addView(draftCard(d));}content.addView(text("CONFIRMED SERVER SCHEDULES",11,ACCENT));JSONArray queued=jobs.optJSONArray("jobs");if(queued!=null)for(int i=0;i<queued.length();i++){JSONObject j=queued.optJSONObject(i);if(j!=null&&j.optString("status").matches("(?i).*queued|scheduled.*"))content.addView(jobCard(j));}}
    private void showAccounts(){content.addView(text("Connect your accounts",23,TEXT));content.addView(text("Choose a channel and sign in securely. You won’t need to enter a server address or pairing code.",12,MUTED));if(!api.configured())serviceBanner();JSONArray list=accounts.optJSONArray("accounts");for(int i=0;i<PLATFORMS.length;i++){String p=PLATFORMS[i];JSONObject match=null;if(list!=null)for(int j=0;j<list.length();j++){JSONObject a=list.optJSONObject(j);if(a!=null&&a.optString("platform").equals(p)){match=a;break;}}boolean connected=match!=null&&match.optBoolean("connected",true);LinearLayout box=column();box.setPadding(dp(8),dp(5),dp(8),dp(8));box.setBackground(card());box.addView(text(LABELS[i],15,TEXT));box.addView(text(connected?match.optString("displayName",match.optString("name","Connected")):platformHint(p),11,connected?0xff83d8ac:MUTED));Button action=button(connected?"Reconnect account":(api.configured()?"Connect account":"Coming soon"),()->startConnect(p));action.setEnabled(api.configured());box.addView(action);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.bottomMargin=dp(8);box.setLayoutParams(lp);content.addView(box);} }
    private String platformHint(String p){switch(p){case"facebook":return"Page publishing · Facebook Page admin access required";case"linkedin":return"Member or organization publishing · provider approval may apply";case"tiktok":return"Direct Post · app review required for public posts";default:return"Channel upload · Google OAuth and API project required";}}
    private String channelSummary(Collection<String> ids){ArrayList<String> names=new ArrayList<>();for(int i=0;i<PLATFORMS.length;i++)if(ids.contains(PLATFORMS[i]))names.add(LABELS[i]);return String.join("  ·  ",names);}
    private void serviceSettings(){EditText field=new EditText(this);field.setSingleLine();field.setTextColor(TEXT);field.setHintTextColor(MUTED);field.setHint("https://publish.your-domain.com");field.setText(prefs.getString("service_url",""));new AlertDialog.Builder(this).setTitle("Publishing service").setMessage("Enter your deployed HTTPS service URL. OAuth secrets and platform tokens belong on that service, never in this Android app.").setView(field).setNegativeButton("Cancel",null).setNeutralButton("Test connection",(d,w)->saveService(field.getText().toString(),true)).setPositiveButton("Save",(d,w)->saveService(field.getText().toString(),false)).show();}
    private void saveService(String value,boolean test){if(!BuildConfig.DEBUG){showPublishingSetup();return;}String url=PublishApiClient.normalize(value);if(!url.isEmpty()&&!url.startsWith("https://")&&!url.matches("http://(localhost|127\\.0\\.0\\.1|10\\.0\\.2\\.2)(:[0-9]+)?")){toast("Use HTTPS for the publishing service");return;}String previous=PublishApiClient.normalize(prefs.getString("service_url",""));if(!previous.equals(url))PublishCredentialStore.clear(this);prefs.edit().putString("service_url",url).apply();api=new PublishApiClient(this,url,PublishCredentialStore.load(this));if(url.isEmpty()){accounts=jobs=new JSONObject();render();return;}if(test){AlertDialog progress=busy("Testing secure connection…");PublishApiClient current=api;io.execute(()->{String failure="";JSONObject health=null;try{health=current.health();}catch(Exception e){failure=e.getMessage();}JSONObject result=health;String error=failure;runOnUiThread(()->{progress.dismiss();if(!error.isEmpty())toast("Service connection failed: "+error);else{toast("Connected · "+result.optString("service","publishing service"));refreshServiceData();}});});}else{render();refreshServiceData();}}
    private void refreshServiceData(){if(!api.configured()||PublishCredentialStore.load(this).isEmpty())return;PublishApiClient current=api;io.execute(()->{JSONObject a=null,j=null;String failure="";try{a=current.accounts();j=current.jobs();}catch(Exception e){failure=e.getMessage()==null?"Network error":e.getMessage();}JSONObject aa=a,jj=j;String error=failure;runOnUiThread(()->{if(current!=api||isFinishing())return;if(!error.isEmpty()){if(section.equals("Accounts"))toast("Could not load accounts: "+error);return;}accounts=aa==null?new JSONObject():aa;jobs=jj==null?new JSONObject():jj;render();});});}
    private void startConnect(String provider){if(!api.configured()){showPublishingSetup();return;}AlertDialog progress=busy("Opening secure sign-in…");PublishApiClient current=api;String deviceId=prefs.getString("device_id","");if(deviceId.isEmpty()){deviceId=UUID.randomUUID().toString();prefs.edit().putString("device_id",deviceId).apply();}String installId=deviceId;io.execute(()->{JSONObject response=null;String failure="";try{response=current.connect(provider,installId);}catch(Exception e){failure=e.getMessage();}JSONObject result=response;String error=failure;runOnUiThread(()->{progress.dismiss();if(!error.isEmpty()){toast("Could not connect: "+error);return;}String state=result.optString("state"),url=result.optString("authorizationUrl");if(state.isEmpty()||url.isEmpty()){toast("Sign-in couldn’t start. Please try again.");return;}prefs.edit().putString("oauth_state_"+provider,state).apply();try{startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse(url)));}catch(Exception e){toast("No browser is available for account sign-in");}});});}
    @Override protected void onNewIntent(Intent intent){super.onNewIntent(intent);setIntent(intent);handleOAuth(intent);}
    private void handleOAuth(Intent intent){Uri uri=intent==null?null:intent.getData();if(uri==null||!"solocamera".equals(uri.getScheme())||!"oauth".equals(uri.getHost()))return;String provider=uri.getQueryParameter("provider"),state=uri.getQueryParameter("state"),ticket=uri.getQueryParameter("ticket");if(provider==null||state==null||ticket==null||!Arrays.asList(PLATFORMS).contains(provider)||!state.equals(prefs.getString("oauth_state_"+provider,""))||!api.configured()){toast("Sign-in could not be verified. Please connect the account again.");return;}prefs.edit().remove("oauth_state_"+provider).apply();AlertDialog progress=busy("Finishing account sign-in…");PublishApiClient current=api;String installId=prefs.getString("device_id","");io.execute(()->{JSONObject result=null;String failure="";try{result=current.completeOAuth(provider,state,ticket,installId);String access=result.optString("accessToken");if(!access.isEmpty())PublishCredentialStore.save(this,access);}catch(Exception e){failure=e.getMessage();}JSONObject r=result;String error=failure;runOnUiThread(()->{progress.dismiss();if(!error.isEmpty())toast("Sign-in failed: "+error);else{toast("Account connected");api=new PublishApiClient(this,configuredServiceUrl(),PublishCredentialStore.load(this));refreshServiceData();render();}});});}
    private void newComposer(){editingDraft=null;pickedMedia=null;pickedName="";pickedSize=0;scheduledAt=0;showComposer(null);}
    private void editComposer(PublishDraftStore.Draft draft){editingDraft=draft;pickedMedia=draft.mediaUri.isEmpty()?null:Uri.parse(draft.mediaUri);pickedName=draft.mediaName;pickedSize=0;scheduledAt=draft.scheduledAt;showComposer(draft);}
    private void showComposer(PublishDraftStore.Draft draft){LinearLayout panel=column();panel.setPadding(dp(10),dp(4),dp(10),dp(4));mediaLine=text(pickedMedia==null?"No video selected":pickedName+(pickedSize>0?" · "+readable(pickedSize):""),12,MUTED);panel.addView(mediaLine);panel.addView(button("＋  Choose exported video",this::pickVideo));captionField=new EditText(this);captionField.setTextColor(TEXT);captionField.setHintTextColor(MUTED);captionField.setHint("Write a caption…");captionField.setGravity(Gravity.TOP|Gravity.START);captionField.setMinLines(3);captionField.setMaxLines(7);captionField.setFilters(new InputFilter[]{new InputFilter.LengthFilter(2200)});if(draft!=null)captionField.setText(draft.caption);panel.addView(captionField,new LinearLayout.LayoutParams(-1,dp(116)));panel.addView(text("POST TO",11,ACCENT));channelBoxes.clear();for(int i=0;i<PLATFORMS.length;i++){CheckBox check=new CheckBox(this);check.setText(LABELS[i]+(PLATFORMS[i].equals("facebook")?" · Pages":""));check.setTextColor(TEXT);check.setButtonTintList(android.content.res.ColorStateList.valueOf(ACCENT));check.setChecked(draft!=null?draft.platforms.contains(PLATFORMS[i]):false);channelBoxes.put(PLATFORMS[i],check);panel.addView(check);}panel.addView(button("Channel options",this::editChannelSettings));scheduleLine=text(scheduleLabel(),12,ACCENT);panel.addView(scheduleLine);panel.addView(button("◷  Choose date and time",this::chooseDateTime));panel.addView(text("Time uses "+TimeZone.getDefault().getID()+". Each platform can enforce its own media length, caption, audience and review limits. The service checks those before accepting the schedule.",10,MUTED));ScrollView scroll=new ScrollView(this);scroll.setFillViewport(false);scroll.addView(panel);AlertDialog dialog=new AlertDialog.Builder(this).setTitle(draft==null?"New post":"Edit local draft").setView(scroll).setNegativeButton("Cancel",null).setNeutralButton("Save draft",null).setPositiveButton("Schedule",null).create();composer=dialog;dialog.setOnShowListener(v->{dialog.getButton(AlertDialog.BUTTON_NEUTRAL).setOnClickListener(b->saveLocalDraft());dialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(b->{if(scheduledAt<=System.currentTimeMillis()){toast("Choose a future date and time");return;}submitPost(true);});Button now=button("Publish now",()->submitPost(false));panel.addView(now);});dialog.show();}
    private void pickVideo(){Intent pick=new Intent(Intent.ACTION_OPEN_DOCUMENT).setType("video/*").addCategory(Intent.CATEGORY_OPENABLE);pick.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION);try{startActivityForResult(pick,71);}catch(Exception e){toast("No video picker is available");}}
    @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request!=71||result!=RESULT_OK||data==null||data.getData()==null)return;pickedMedia=data.getData();try{getContentResolver().takePersistableUriPermission(pickedMedia,Intent.FLAG_GRANT_READ_URI_PERMISSION);}catch(SecurityException ignored){}pickedName=displayName(pickedMedia);pickedSize=sizeOf(pickedMedia);if(mediaLine!=null)mediaLine.setText(pickedName+" · "+readable(pickedSize));}
    private void chooseDateTime(){Calendar c=Calendar.getInstance();if(scheduledAt>0)c.setTimeInMillis(scheduledAt);new DatePickerDialog(this,(view,y,m,d)->{Calendar chosen=Calendar.getInstance();chosen.set(y,m,d);new TimePickerDialog(this,(t,h,min)->{chosen.set(Calendar.HOUR_OF_DAY,h);chosen.set(Calendar.MINUTE,min);chosen.set(Calendar.SECOND,0);chosen.set(Calendar.MILLISECOND,0);scheduledAt=chosen.getTimeInMillis();scheduleLine.setText(scheduleLabel());},c.get(Calendar.HOUR_OF_DAY),c.get(Calendar.MINUTE),true).show();},c.get(Calendar.YEAR),c.get(Calendar.MONTH),c.get(Calendar.DAY_OF_MONTH)).show();}
    private String scheduleLabel(){return scheduledAt>0?"◷  "+DateFormat.getDateTimeInstance(DateFormat.MEDIUM,DateFormat.SHORT).format(new Date(scheduledAt))+" · "+TimeZone.getDefault().getID():"◷  Publish time · choose a date and time";}
    private void editChannelSettings(){ArrayList<String> selected=new ArrayList<>();for(Map.Entry<String,CheckBox> e:channelBoxes.entrySet())if(e.getValue().isChecked())selected.add(e.getKey());if(selected.isEmpty()){toast("Select a channel first");return;}if(selected.size()>1){String[] names=new String[selected.size()];for(int i=0;i<names.length;i++)names[i]=LABELS[indexOf(selected.get(i))];new AlertDialog.Builder(this).setTitle("Channel-specific settings").setItems(names,(d,which)->editOneChannel(selected.get(which))).setNegativeButton("Done",null).show();}else editOneChannel(selected.get(0));}
    private int indexOf(String provider){for(int i=0;i<PLATFORMS.length;i++)if(PLATFORMS[i].equals(provider))return i;return 0;}
    private JSONObject channelOptions(String provider){JSONObject options=editingDraft==null?new JSONObject():editingDraft.channelOptions.optJSONObject(provider);if(options==null)options=new JSONObject();if(editingDraft!=null)try{options=new JSONObject(editingDraft.channelOptions.optJSONObject(provider)==null?"{}":editingDraft.channelOptions.getJSONObject(provider).toString());}catch(Exception ignored){}return options;}
    private void storeChannelOptions(String provider,JSONObject options){if(editingDraft==null)editingDraft=new PublishDraftStore.Draft();try{editingDraft.channelOptions.put(provider,options);}catch(JSONException e){toast("Could not save channel settings");}}
    private void editOneChannel(String provider){JSONObject options=channelOptions(provider);if(provider.equals("facebook")){JSONArray all=accounts.optJSONArray("accounts");ArrayList<JSONObject> pages=new ArrayList<>();ArrayList<String> names=new ArrayList<>();if(all!=null)for(int i=0;i<all.length();i++){JSONObject a=all.optJSONObject(i);if(a!=null&&provider.equals(a.optString("platform"))){pages.add(a);names.add(a.optString("displayName",a.optString("name","Facebook Page")));}}if(pages.isEmpty()){new AlertDialog.Builder(this).setTitle("Facebook Page").setMessage("Connect Facebook and choose an eligible Page in the service account flow. Personal profile publishing is not supported by this integration.").setPositiveButton("OK",null).show();return;}new AlertDialog.Builder(this).setTitle("Publish to Page").setItems(names.toArray(new String[0]),(d,i)->{try{options.put("accountId",pages.get(i).optString("id"));storeChannelOptions(provider,options);}catch(JSONException ignored){}}).setNegativeButton("Cancel",null).show();return;}
        if(provider.equals("tiktok")){JSONObject account=findAccount(provider);JSONObject creator=account==null?null:account.optJSONObject("creatorInfo");JSONArray permitted=creator==null?null:creator.optJSONArray("privacyLevelOptions");if(permitted==null||permitted.length()==0){new AlertDialog.Builder(this).setTitle("TikTok post settings").setMessage("Connect TikTok to load this creator’s allowed privacy levels. The app must display the levels returned by TikTok before Direct Post.").setPositiveButton("OK",null).show();return;}String[] values=new String[permitted.length()];for(int i=0;i<values.length;i++)values[i]=permitted.optString(i);new AlertDialog.Builder(this).setTitle("TikTok audience").setItems(values,(d,i)->{try{options.put("privacyLevel",values[i]);storeChannelOptions(provider,options);}catch(JSONException ignored){}}).setNegativeButton("Cancel",null).show();return;}
        if(provider.equals("youtube")){EditText title=new EditText(this);title.setSingleLine();title.setTextColor(TEXT);title.setHint("Video title");title.setText(options.optString("title",""));Spinner privacy=new Spinner(this);String[] values={"private","unlisted","public"};privacy.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,values){public View getView(int i,View v,android.view.ViewGroup p){TextView t=(TextView)super.getView(i,v,p);t.setTextColor(TEXT);return t;}});privacy.setSelection(Math.max(0,Arrays.asList(values).indexOf(options.optString("privacyStatus","private"))));CheckBox kids=new CheckBox(this);kids.setText("Made for kids");kids.setTextColor(TEXT);kids.setChecked(options.optBoolean("madeForKids"));LinearLayout view=column();view.addView(title);view.addView(privacy);view.addView(kids);new AlertDialog.Builder(this).setTitle("YouTube details").setView(view).setNegativeButton("Cancel",null).setPositiveButton("Save",(d,w)->{try{options.put("title",title.getText().toString().trim()).put("privacyStatus",values[privacy.getSelectedItemPosition()]).put("madeForKids",kids.isChecked());storeChannelOptions(provider,options);}catch(JSONException ignored){}}).show();return;}
        new AlertDialog.Builder(this).setTitle("LinkedIn post target").setItems(new String[]{"Personal member feed","Organization Page"},(d,which)->{if(which==0){try{options.put("authorType","member");options.remove("authorId");storeChannelOptions(provider,options);}catch(JSONException ignored){}return;}JSONArray all=accounts.optJSONArray("accounts");ArrayList<JSONObject> organizations=new ArrayList<>();ArrayList<String> names=new ArrayList<>();if(all!=null)for(int i=0;i<all.length();i++){JSONObject a=all.optJSONObject(i);if(a!=null&&provider.equals(a.optString("platform"))&&(a.optString("type").equalsIgnoreCase("organization")||a.optString("kind").equalsIgnoreCase("organization"))){organizations.add(a);names.add(a.optString("displayName",a.optString("name","LinkedIn organization")));}}if(organizations.isEmpty()){new AlertDialog.Builder(this).setTitle("No eligible organization").setMessage("Connect LinkedIn and grant organization publishing access to a Page where you have an eligible admin role.").setPositiveButton("OK",null).show();return;}new AlertDialog.Builder(this).setTitle("Choose organization").setItems(names.toArray(new String[0]),(x,index)->{try{options.put("authorType","organization").put("authorId",organizations.get(index).optString("id"));storeChannelOptions(provider,options);}catch(JSONException ignored){}}).setNegativeButton("Cancel",null).show();}).setNegativeButton("Cancel",null).show();}
    private JSONObject findAccount(String provider){JSONArray all=accounts.optJSONArray("accounts");if(all==null)return null;for(int i=0;i<all.length();i++){JSONObject a=all.optJSONObject(i);if(a!=null&&provider.equals(a.optString("platform")))return a;}return null;}
    private PublishDraftStore.Draft collectDraft(){PublishDraftStore.Draft d=editingDraft==null?new PublishDraftStore.Draft():editingDraft;d.mediaUri=pickedMedia==null?"":pickedMedia.toString();d.mediaName=pickedName;d.caption=captionField.getText().toString().trim();d.scheduledAt=scheduledAt;d.platforms.clear();for(Map.Entry<String,CheckBox> e:channelBoxes.entrySet())if(e.getValue().isChecked())d.platforms.add(e.getKey());return d;}
    private void saveLocalDraft(){PublishDraftStore.Draft d=collectDraft();if(d.platforms.isEmpty()){toast("Choose at least one channel");return;}upsertDraft(d);if(composer!=null)composer.dismiss();render();toast("Saved on this phone · not yet scheduled on any platform");}
    private void submitPost(boolean scheduled){PublishDraftStore.Draft d=collectDraft();if(d.platforms.isEmpty()){toast("Choose at least one channel");return;}if(pickedMedia==null){toast("Choose an exported video first");return;}if(scheduled&&(scheduledAt<=System.currentTimeMillis())){toast("Choose a future date and time");return;}if(!api.configured()||PublishCredentialStore.load(this).isEmpty()){d.state="draft";d.error="Saved on this phone. Online publishing is not available yet.";upsertDraft(d);if(composer!=null)composer.dismiss();render();toast("Saved on this phone. Online publishing is being prepared.");return;}d.state="uploading";d.error="";upsertDraft(d);if(composer!=null)composer.dismiss();AlertDialog progress=busy("Preparing secure upload…");PublishApiClient client=api;Uri media=pickedMedia;String fileName=pickedName;long fileSize=pickedSize;String timezone=TimeZone.getDefault().getID();io.execute(()->{String failure="";JSONObject response=null;try{String type=getContentResolver().getType(media);if(type==null||!type.startsWith("video/"))type="video/mp4";if(fileSize<=0)throw new IOException("Could not read the selected file size");PublishApiClient.Upload upload=client.beginUpload(fileName,type,fileSize);client.upload(upload,media,type,(sent,total)->runOnUiThread(()->{if(progress.isShowing())progress.setMessage("Uploading video · "+readable(sent)+" of "+readable(total));}));JSONObject finalized=client.completeUpload(upload.id);if(!"ready".equalsIgnoreCase(finalized.optString("status")))throw new IOException("The publishing service could not verify this upload yet. Your draft was kept on this phone.");response=client.createJob(upload.id,d,timezone);String confirmedId=response.optString("jobId",response.optString("id"));if(confirmedId.isEmpty())throw new IOException("The service response did not include a confirmed job ID. The draft was kept on this phone.");}catch(Exception e){failure=e.getMessage()==null?"Submission failed":e.getMessage();}JSONObject result=response;String error=failure;runOnUiThread(()->{progress.dismiss();if(isFinishing())return;if(!error.isEmpty()){d.state="draft";d.error=error;upsertDraft(d);render();new AlertDialog.Builder(this).setTitle("Post not confirmed").setMessage(error).setPositiveButton("OK",null).show();return;}d.serverId=result.optString("jobId",result.optString("id"));String status=result.optString("status",scheduled?"queued":"publishing");removeDraft(d);jobs=new JSONObject();render();refreshServiceData();toast("Confirmed by publishing service · "+status);});});}
    private void upsertDraft(PublishDraftStore.Draft d){boolean replaced=false;for(int i=0;i<drafts.size();i++)if(drafts.get(i).id.equals(d.id)){drafts.set(i,d);replaced=true;break;}if(!replaced)drafts.add(0,d);try{PublishDraftStore.save(this,drafts);}catch(Exception e){toast("Could not save local draft");}}
    private void deleteDraft(PublishDraftStore.Draft d){if(!d.serverId.isEmpty()){new AlertDialog.Builder(this).setTitle("This post was sent to the service").setMessage("Deleting this local item will not cancel its server job. Use the service queue to cancel or change it.").setPositiveButton("Remove from phone",(x,w)->removeDraft(d)).setNegativeButton("Keep",null).show();}else removeDraft(d);}
    private void removeDraft(PublishDraftStore.Draft d){drafts.remove(d);try{PublishDraftStore.save(this,drafts);}catch(Exception ignored){}render();}
    private AlertDialog busy(String message){ProgressDialog p=new ProgressDialog(this);p.setMessage(message);p.setIndeterminate(true);p.setCancelable(false);p.show();return p;}
    private String displayName(Uri uri){try(Cursor c=getContentResolver().query(uri,new String[]{OpenableColumns.DISPLAY_NAME},null,null,null)){if(c!=null&&c.moveToFirst())return c.getString(0);}catch(Exception ignored){}return"Selected video";}
    private long sizeOf(Uri uri){try(Cursor c=getContentResolver().query(uri,new String[]{OpenableColumns.SIZE},null,null,null)){if(c!=null&&c.moveToFirst())return c.getLong(0);}catch(Exception ignored){}try(android.content.res.AssetFileDescriptor f=getContentResolver().openAssetFileDescriptor(uri,"r")){return f==null?0:f.getLength();}catch(Exception ignored){return 0;}}
    private String readable(long bytes){if(bytes<=0)return"size unknown";return String.format(Locale.ROOT,"%.1f MB",bytes/1048576.0);}
    private void toast(String message){Toast.makeText(this,message,Toast.LENGTH_LONG).show();}
    @Override protected void onDestroy(){if(busy!=null&&busy.isShowing())busy.dismiss();io.shutdown();super.onDestroy();}
}

